def soma(a: float, b: float) -> float:
    """Retorna a soma de a e b."""
    return a + b

def subtrai(a: float, b: float) -> float:
    """Retorna a subtração de a por b."""
    return a - b

def multiplica(a: float, b: float) -> float:
    """Retorna a multiplicação de a por b."""
    return a * b

def divide(a: float, b: float) -> float:
    """Retorna a divisão de a por b. Levanta ValueError se b==0."""
    if b == 0:
        raise ValueError("Divisão por zero não é permitida.")
    return a / b

def main():
    print("Calculadora Simples em Python")
    print("Selecione a operação:")
    print("1. Soma")
    print("2. Subtração")
    print("3. Multiplicação")
    print("4. Divisão")

    op = input("Escolha (1/2/3/4): ")

    try:
        a = float(input("Digite o primeiro número: "))
        b = float(input("Digite o segundo número: "))
    except ValueError:
        print("Entrada inválida. Certifique-se de digitar números válidos.")
        return

    try:
        if op == '1':
            resultado = soma(a, b)
            print(f"Resultado: {resultado}")
        elif op == '2':
            resultado = subtrai(a, b)
            print(f"Resultado: {resultado}")
        elif op == '3':
            resultado = multiplica(a, b)
            print(f"Resultado: {resultado}")
        elif op == '4':
            resultado = divide(a, b)
            print(f"Resultado: {resultado}")
        else:
            print("Operação inválida.")
    except ValueError as ve:
        print(f"Erro: {ve}")

if __name__ == "__main__":
    main()

